import React, { useState } from "react";
import Inline from "../Inline";
import Calendar from "./Calendar";
import type { Meta, StoryObj } from "@storybook/react";
import withDarkMode from "../../lib/utils/storybookDecorators";

const meta: Meta<typeof Calendar> = {
  id: "Components/Calendar",
  title: "Components/Date & Time Picker/Calendar",
  component: Calendar,
  argTypes: {
    firstDayOfWeek: {
      control: { type: "number", min: 0, max: 6 },
      description: "First day of the week (0 = Sunday, ...6 = Saturday)",
    },
    formatWeekDay: {
      options: ["short", "long"],
      control: "radio",
      description: "Format of week day names",
    },
    locale: {
      control: { type: "select" },
      options: ["en-GB", "fr-FR", "de-DE"],
      description: "Locale used by the calendar",
    },
    mode: {
      control: false,
      description: "Date selection mode (single, multiple or range)",
    },
    monthCount: {
      control: { type: "number", min: 1 },
      description: "Number of months to display",
    },
    showOutsideDays: {
      control: "boolean",
      description: "Display days from adjacent months",
    },
    yearRange: {
      control: { type: "number", min: 0 },
      description: "Range of years allowed for selection",
    },
    minDate: {
      description: "Defines minimum date that the user can select",
    },
    maxDate: {
      description: "Defines maximum date that the user can select",
    },
    defaultValue: {
      description: "Custom date input format",
    },
    value: {
      description: "Selected date(s)",
    },
  },
  args: {
    firstDayOfWeek: 0,
    formatWeekDay: "long",
    locale: "en-GB",
    mode: "single",
    monthCount: 1,
    showOutsideDays: true,
    yearRange: 100,
  }
};

export default meta;
type Story = StoryObj<typeof Calendar>;

export const Basic: Story = {
  render: (args) => <Calendar {...args} />,
};

// !dev tag is to exclude the stories from rendering in sidebar
export const BasicForVisualTest: Story = {
  tags: ["visual-test", "!dev"],
  play: async ({ mount, args }) => {
    await mount(<Calendar {...args} defaultValue={new Date('2025-03-11T12:00:00.000Z')}/>);
  }
};

export const Range: Story = {
  args: {
    mode: "range",
  },
  render: (args) => <Calendar {...args} />,
};

export const Dark: Story = {
  ...Basic,
  decorators: [withDarkMode],
};

// !dev tag is to exclude the stories from rendering in sidebar
export const DarkForVisualTest: Story = {
  tags: ["visual-test", "!dev"],
  ...BasicForVisualTest,
  decorators: [withDarkMode],
};


export const Multi: Story = {
  args: {
    mode: "multi",
  },
  ...Basic,
};

export const Wide: Story = {
  args: {
    monthCount: 3,
  },
  ...Basic,
};

export const YearRange: Story = {
  args: {
    yearRange: 10,
  },
  ...Basic,
};

export const YearMinMax: Story = {
  parameters: { docs: { source: { type: "code" }}},
  render: () => {
    const CURRENT_YEAR = new Date().getFullYear();
    return (
      <Inline spacing="6-x">
        <Calendar minDate={new Date(CURRENT_YEAR, 0, 1)} />
        <Calendar maxDate={new Date(CURRENT_YEAR, 11, 31)} />
      </Inline>
    );
  },
};

export const Controlled: Story = {
  parameters: { docs: { source: { type: "code" }}},
  render: () => {
    const [value, setValue] = useState(new Date(1980, 11, 18));
    return (
      <>
        <Calendar value={value} onChange={(date: any) => setValue(date)} />
        <p>Selected date is {value.toLocaleDateString()}</p>
      </>
    );
  },
};
